-- Disposable local fixture ONLY, after kyc-quarantine-fixture + quarantine + scanner migrations.
begin;
set role anon;
select public.assert_throws($q$select public.kyc_scan_worker_authorized()$q$,'42501','anonymous cannot claim worker authority');
select public.assert_throws($q$select public.claim_kyc_scan(null,'eicar')$q$,'42501','anonymous cannot trigger scans');
select public.assert_throws($q$select * from private.kyc_scan_attempts$q$,'42501','anonymous cannot read receipts');
reset role;
set role authenticated;
select public.assert_throws($q$select public.kyc_scan_worker_authorized()$q$,'42501','customer cannot claim worker authority');
set local request.jwt.claims='{"role":"service_role"}';
select public.assert_throws($q$select public.kyc_scan_worker_authorized()$q$,'42501','forged claim settings cannot change the authenticated database role');
select public.assert_throws($q$select public.claim_kyc_scan(null,'eicar')$q$,'42501','customer cannot trigger provider');
select public.assert_throws($q$select public.authorize_kyc_scan_dispatch(gen_random_uuid())$q$,'42501','customer cannot admit provider dispatch');
select public.assert_throws($q$select public.finish_kyc_scan(gen_random_uuid(),'clean','provider_clean',repeat('a',64),null,false)$q$,'42501','customer cannot forge clean');
select public.assert_throws($q$update private.kyc_scan_budget set personal_documents_allowed=true$q$,'42501','customer cannot open processing');
reset role;
select public.assert_true(not public.kyc_scan_worker_authorized(),'SQL owner context is not an authenticated PostgREST worker');
select public.assert_true((select not personal_documents_allowed and used=0 and maximum=32 from private.kyc_scan_budget),'zero-use, nonrenewing, private-processing-closed default');
set role service_role;
select public.assert_true(public.kyc_scan_worker_authorized(),'actual database service role can establish worker authority');
select public.assert_true((select used=0 from private.kyc_scan_budget),'authority probe consumes no scan attempt');
select public.assert_throws($q$update private.kyc_scan_budget set personal_documents_allowed=true,processing_review_reference='forged'$q$,'42501','worker cannot authorise personal-data processing');
select public.assert_throws($q$update private.kyc_scan_budget set maximum=600$q$,'42501','worker cannot raise budget');
select public.assert_throws($q$select public.claim_kyc_scan(null,'arbitrary')$q$,'22023','only fixed fixtures allowed');
select public.assert_true(public.claim_kyc_scan('10000000-0000-4000-8000-000000000001',null)->>'reason'='processing_review_pending','no real-document processing before review');
select public.assert_true((select used=0 from private.kyc_scan_budget),'held document consumes no provider attempt');
select public.assert_true(public.claim_kyc_scan(null,'clean_pdf')->>'state'='claimed','first synthetic fixture claims');
select public.assert_true(public.claim_kyc_scan(null,'clean_pdf')->>'cached'='true','simultaneous duplicate returns existing claim');
select public.assert_true((select used=1 from private.kyc_scan_budget),'duplicate does not consume request');
select public.assert_true(public.claim_kyc_scan(null,'eicar')->>'reason'='scanner_busy','single global in-flight provider call');
savepoint before_dispatch_receipt;
select public.assert_true(public.finish_kyc_scan((select id from private.kyc_scan_attempts where fixture='clean_pdf'),'clean','provider_clean',repeat('a',64),null,false)->>'reason'='provider_dispatch_required','no clean receipt without actual dispatch admission');
rollback to savepoint before_dispatch_receipt;
release savepoint before_dispatch_receipt;
savepoint before_expired_dispatch;
reset role;
update private.kyc_scan_budget set lease_expires_at=clock_timestamp()-interval '1 second';
set role service_role;
select public.assert_true(public.authorize_kyc_scan_dispatch((select id from private.kyc_scan_attempts where fixture='clean_pdf'))->>'authorized'='false','delayed worker cannot dispatch after its lease expires');
rollback to savepoint before_expired_dispatch;
release savepoint before_expired_dispatch;
select public.assert_true(public.authorize_kyc_scan_dispatch((select id from private.kyc_scan_attempts where fixture='clean_pdf'))->>'authorized'='true','dispatch rechecks lease after input download');
select public.assert_true(public.authorize_kyc_scan_dispatch((select id from private.kyc_scan_attempts where fixture='clean_pdf'))->>'authorized'='false','one outbound dispatch per claimed attempt');
select public.assert_true(public.finish_kyc_scan((select id from private.kyc_scan_attempts where fixture='clean_pdf'),'clean','provider_clean',repeat('a',64),null,false)->>'state'='clean','clean synthetic receipt accepted');
select public.assert_true(public.finish_kyc_scan((select id from private.kyc_scan_attempts where fixture='clean_pdf'),'blocked','provider_rejected',repeat('b',64),null,true)->>'state'='clean','terminal receipt cannot be overwritten');
reset role;
update private.kyc_scan_budget set next_request_at=clock_timestamp()-interval '1 second';
set role service_role;
select public.assert_true(public.claim_kyc_scan(null,'eicar')->>'state'='claimed','second fixed synthetic fixture claims');
select public.authorize_kyc_scan_dispatch((select id from private.kyc_scan_attempts where fixture='eicar'));
select public.assert_true(public.finish_kyc_scan((select id from private.kyc_scan_attempts where fixture='eicar'),'blocked','provider_rejected',repeat('b',64),null,true)->>'malwareDetected'='true','malware verdict recorded without filenames');
select public.assert_true((select used=2 from private.kyc_scan_budget),'exactly two fixed test attempts');
select public.assert_true(public.claim_kyc_scan(null,'eicar')->>'cached'='true','repeated evaluation never resends');
select public.assert_throws($q$update private.kyc_scan_attempts set sha256=repeat('c',64)$q$,'42501','input fingerprint immutable to worker');
select public.register_quarantined_kyc_document('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','id','00000000-0000-4000-8000-000000000001/id.pdf','20000000-0000-4000-8000-000000000001','2026-10-26T00:00:00Z',repeat('a',64),'application/pdf',12);
reset role;
-- Synthetic local review authority only; NEVER copy this activation into hosted data.
select public.assert_throws($q$update private.kyc_scan_budget set personal_documents_allowed=true$q$,'23514','processing review reference required even to owner');
update private.kyc_scan_budget set personal_documents_allowed=true,processing_review_reference='synthetic local test review authority',next_request_at=clock_timestamp()-interval '1 second';
set role service_role;
select public.assert_true(public.claim_kyc_scan((select document_id from private.kyc_quarantine_receipts limit 1),null)->>'state'='claimed','sealed registered synthetic object claims');
select public.authorize_kyc_scan_dispatch((select id from private.kyc_scan_attempts where document_id is not null));
reset role;
update storage.objects set updated_at='2026-10-27T00:00:00Z' where name like '%/id.pdf';
set role service_role;
select public.assert_true(public.finish_kyc_scan((select id from private.kyc_scan_attempts where document_id is not null),'clean','provider_clean',repeat('c',64),repeat('a',64),false)->>'state'='error','object change before final commit overrides clean provider');
select public.assert_true((select reason='object_changed' from private.kyc_scan_attempts where document_id is not null),'TOCTOU refusal recorded');
select public.assert_true((select bool_and(status='pending') from public.xooter_documents),'scanning does not approve authenticity');
select public.assert_throws($q$update public.xooter_applications set status='approved'$q$,'23514','malware plumbing cannot activate worker');
select public.assert_throws($q$insert into public.xooters(user_id,active) values('00000000-0000-4000-8000-000000000001',true)$q$,'23514','contractor activation interlock retained');
reset role;
set role authenticated;
select public.assert_true((select count(*)=0 from storage.objects where bucket_id='kyc-docs'),'scan does not expose raw files to browser');
reset role;
commit;
